mapper.select:
SELECT
c.id, c.conversation_type, c.title, c.last_message_id,
c.last_message_time, c.created_time, c.updated_time
FROM t_conversation c
INNER JOIN t_conversation_participant cp ON c.id = cp.conversation_id
WHERE cp.user_id = #{userId,jdbcType=BIGINT}
AND cp.is_active = 1

  AND c.conversation_type = #{conversationType,jdbcType=TINYINT}


  AND (c.last_message_time < (
  SELECT last_message_time FROM t_conversation WHERE id = #{cursor,jdbcType=BIGINT}
  ) OR (c.last_message_time = (
  SELECT last_message_time FROM t_conversation WHERE id = #{cursor,jdbcType=BIGINT}
  ) AND c.id < #{cursor,jdbcType=BIGINT}))

ORDER BY c.last_message_time DESC, c.id DESC
LIMIT #{limit,jdbcType=INTEGER}

mapper.update:
UPDATE t_conversation
SET last_message_id = #{lastMessageId,jdbcType=BIGINT},
    last_message_time = #{lastMessageTime,jdbcType=TIMESTAMP},
    updated_time = #{updatedTime,jdbcType=TIMESTAMP}
WHERE id = #{id,jdbcType=BIGINT}
